import React, { useState, useEffect } from 'react';
import { User, Menu, X, Shield, LogOut } from 'lucide-react';
import Login from './Login';
import AdminLogin from './AdminLogin';
import '../styles/styles.css';

// Import logo image
import logoImage from '../logoDavideTaddia.jpeg';

const Navbar = ({ onHireMeClick }) => {
  // State management
  const [menuOpen, setMenuOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);
  const [logoError, setLogoError] = useState(false);
  const [showLogin, setShowLogin] = useState(false);
  const [showAdminLogin, setShowAdminLogin] = useState(false);
  const [showUserDropdown, setShowUserDropdown] = useState(false);
  
  // Auth state
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [isAdmin, setIsAdmin] = useState(false);
  const [user, setUser] = useState(null);

  // Check for existing authentication on component mount
  useEffect(() => {
    // Check for admin auth
    const adminData = localStorage.getItem('adminData');
    if (adminData) {
      try {
        const parsedData = JSON.parse(adminData);
        setUser(parsedData);
        setIsAuthenticated(true);
        setIsAdmin(true);
      } catch (error) {
        console.error('Error parsing admin data:', error);
        localStorage.removeItem('adminData');
      }
    } else {
      // Check for regular user auth
      const userData = localStorage.getItem('userData');
      if (userData) {
        try {
          const parsedData = JSON.parse(userData);
          setUser(parsedData);
          setIsAuthenticated(true);
          setIsAdmin(false);
        } catch (error) {
          console.error('Error parsing user data:', error);
          localStorage.removeItem('userData');
        }
      }
    }
  }, []);

  // Handle scroll for navbar styling
  useEffect(() => {
    const handleScroll = () => {
      const offset = window.scrollY;
      if (offset > 50) {
        setScrolled(true);
      } else {
        setScrolled(false);
      }
    };

    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  // Handle login success (regular users)
  const handleLoginSuccess = (userData) => {
    setUser(userData);
    setIsAuthenticated(true);
    setIsAdmin(false);
    setShowLogin(false);
  };

  // Handle admin login success
  const handleAdminLoginSuccess = (adminData) => {
    setUser(adminData);
    setIsAuthenticated(true);
    setIsAdmin(true);
    setShowAdminLogin(false);
  };

  // Handle logout
  const handleLogout = () => {
    if (isAdmin) {
      localStorage.removeItem('adminData');
    } else {
      localStorage.removeItem('userData');
    }
    setUser(null);
    setIsAuthenticated(false);
    setIsAdmin(false);
    setShowUserDropdown(false);
  };

  // Handle "Let's Talk" button click
  const handleHireMeClick = () => {
    setMenuOpen(false);
    onHireMeClick();
  };

  // Logo fallback component
  const LogoFallback = () => (
    <div className="w-10 h-10 md:w-12 md:h-12 flex items-center justify-center text-dark-highlight font-bold text-xl bg-transparent rounded-full border-2 border-dark-highlight">
      <span className="font-mono">DT</span>
    </div>
  );

  return (
    <div className="fixed top-0 left-0 right-0 z-50 flex justify-center px-4 transition-all duration-300">
      <nav className={`max-w-[1440px] w-full mx-auto px-4 md:px-6 py-4 flex items-center justify-between navbar-green-black rounded-lg ${
        scrolled ? 'mt-2 shadow-lg' : 'mt-4'
      }`}>
        <div className="flex items-center">
          <a href="/" className="flex items-center">
            {!logoError ? (
              <div className="w-10 h-10 md:w-12 md:h-12 rounded-full overflow-hidden border-2 border-dark-highlight flex items-center justify-center">
                <img 
                  src={logoImage}
                  alt="Logo Davide Taddia"
                  className="w-full h-full object-cover"
                  onError={() => setLogoError(true)}
                />
              </div>
            ) : (
              <LogoFallback />
            )}
          </a>
        </div>

        {/* Mobile menu button */}
        <button 
          className="md:hidden text-action focus:outline-none"
          onClick={() => setMenuOpen(!menuOpen)}
          aria-label={menuOpen ? "Close menu" : "Open menu"}
        >
          {menuOpen ? (
            <X size={24} />
          ) : (
            <Menu size={24} />
          )}
        </button>

        {/* Desktop navigation */}
        <div className="hidden md:flex items-center gap-8">
          <div className="flex gap-4 lg:gap-6">
            <a href="/masteryhub" className="text-action hover:text-primary transition-colors">00 MasteryHub</a>
            <a href="/wikidedia" className="text-action hover:text-primary transition-colors">01 WikIDEDIA</a>
            <a href="/servicehub" className="text-action hover:text-primary transition-colors">02 ServiceHub</a>
          </div>

          {/* Auth options */}
          {isAuthenticated ? (
            <div className="relative">
              <button 
                onClick={() => setShowUserDropdown(!showUserDropdown)}
                className={`flex items-center gap-2 py-2 px-4 rounded-lg transition-colors ${
                  isAdmin 
                    ? 'bg-green-600/20 hover:bg-green-600/30 text-green-400' 
                    : 'bg-blue-600/20 hover:bg-blue-600/30 text-blue-400'
                }`}
              >
                <div className="w-6 h-6 rounded-full bg-current flex items-center justify-center">
                  <span className="text-black text-xs font-bold">
                    {user?.name?.charAt(0) || 'U'}
                  </span>
                </div>
                <span>{isAdmin ? 'Admin' : user?.name || 'User'}</span>
                {isAdmin && <Shield size={14} />}
              </button>
              
              {/* User dropdown */}
              {showUserDropdown && (
                <div className="absolute right-0 mt-2 w-48 bg-gray-800 rounded-lg shadow-lg overflow-hidden z-10 border border-gray-700">
                  <div className="p-3 border-b border-gray-700">
                    <p className="font-medium text-white">{user?.name || 'User'}</p>
                    <p className="text-sm text-gray-400">{user?.email || user?.username || ''}</p>
                    {isAdmin && (
                      <span className="inline-flex items-center mt-1 px-2 py-0.5 rounded text-xs bg-green-900 text-green-400">
                        <Shield size={10} className="mr-1" />
                        Administrator
                      </span>
                    )}
                  </div>
                  <div className="py-1">
                    {isAdmin && (
                      <a 
                        href="/admin" 
                        className="block px-4 py-2 text-white hover:bg-gray-700 transition-colors"
                      >
                        Admin Dashboard
                      </a>
                    )}
                    <button
                      onClick={handleLogout}
                      className="w-full text-left px-4 py-2 text-red-400 hover:bg-gray-700 transition-colors flex items-center"
                    >
                      <LogOut size={14} className="mr-2" />
                      Sign Out
                    </button>
                  </div>
                </div>
              )}
            </div>
          ) : (
            <div className="flex items-center gap-2">
              <button 
                onClick={() => setShowLogin(true)}
                className="flex items-center justify-center gap-1 bg-blue-600/20 hover:bg-blue-600/30 text-blue-400 py-2 px-3 rounded-lg transition-colors text-sm"
              >
                <User size={16} />
                <span>Sign In</span>
              </button>
              
              <button
                onClick={() => setShowAdminLogin(true)}
                className="flex items-center justify-center gap-1 bg-green-600/20 hover:bg-green-600/30 text-green-400 py-2 px-3 rounded-lg transition-colors text-sm"
              >
                <Shield size={16} />
                <span>Admin</span>
              </button>
            </div>
          )}

          <button 
            onClick={handleHireMeClick}
            className="btn-primary px-6 py-3 rounded-lg transition-colors pulse-animation text-xl font-bold"
          >
            Let's Talk
          </button>
        </div>

        {/* Mobile menu */}
        {menuOpen && (
          <div className="absolute top-16 right-4 left-4 card-bg shadow-lg rounded-lg p-4 md:hidden">
            <div className="flex flex-col gap-4">
              <a 
                href="/masteryhub" 
                className="text-action hover:text-primary py-2"
                onClick={() => setMenuOpen(false)}
              >
                00 MasteryHub
              </a>
              <a 
                href="/wikidedia" 
                className="text-action hover:text-primary py-2"
                onClick={() => setMenuOpen(false)}
              >
                01 WikIDEDIA
              </a>
              <a 
                href="/servicehub" 
                className="text-action hover:text-primary py-2"
                onClick={() => setMenuOpen(false)}
              >
                02 ServiceHub
              </a>
              
              {/* Auth options in mobile menu */}
              {isAuthenticated ? (
                <div className="border-t border-gray-700 pt-2">
                  <div className="flex items-center py-2">
                    <div className={`w-8 h-8 rounded-full mr-2 ${isAdmin ? 'bg-green-500' : 'bg-blue-500'} flex items-center justify-center`}>
                      <span className="text-black font-bold">{user?.name?.charAt(0) || 'U'}</span>
                    </div>
                    <div>
                      <p className="text-white">{user?.name || 'User'}</p>
                      <p className="text-sm text-gray-400">{isAdmin ? 'Administrator' : 'User'}</p>
                    </div>
                  </div>
                  
                  {isAdmin && (
                    <a 
                      href="/admin" 
                      className="block py-2 text-green-400 hover:text-green-300"
                      onClick={() => setMenuOpen(false)}
                    >
                      Admin Dashboard
                    </a>
                  )}
                  
                  <button 
                    onClick={handleLogout}
                    className="py-2 text-red-400 hover:text-red-300 flex items-center"
                  >
                    <LogOut size={16} className="mr-2" />
                    Sign Out
                  </button>
                </div>
              ) : (
                <div className="border-t border-gray-700 pt-2 flex flex-col gap-2">
                  <button 
                    onClick={() => {
                      setShowLogin(true);
                      setMenuOpen(false);
                    }}
                    className="py-2 text-blue-400 hover:text-blue-300 flex items-center"
                  >
                    <User size={16} className="mr-2" />
                    Sign In
                  </button>
                  
                  <button 
                    onClick={() => {
                      setShowAdminLogin(true);
                      setMenuOpen(false);
                    }}
                    className="py-2 text-green-400 hover:text-green-300 flex items-center"
                  >
                    <Shield size={16} className="mr-2" />
                    Admin Login
                  </button>
                </div>
              )}
              
              <button 
                onClick={handleHireMeClick}
                className="btn-primary px-4 py-2 rounded-lg transition-colors pulse-animation mt-2 text-xl font-bold"
              >
                Let's Talk
              </button>
            </div>
          </div>
        )}
      </nav>

      {/* Login Modals */}
      {showLogin && <Login onClose={() => setShowLogin(false)} onLoginSuccess={handleLoginSuccess} />}
      {showAdminLogin && <AdminLogin onClose={() => setShowAdminLogin(false)} onLoginSuccess={handleAdminLoginSuccess} />}
    </div>
  );
};

export default Navbar;