import React, { useState } from 'react';
import { X, LogIn, User, Lock } from 'lucide-react';

const AdminLogin = ({ onClose, onLoginSuccess }) => {
  // State management
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');

  // Handle form submission
  const handleSubmit = async (e) => {
    e.preventDefault();
    
    if (!username || !password) {
      setError('Please enter both username and password');
      return;
    }
    
    setIsLoading(true);
    setError('');
    
    try {
      // Simulate API delay
      await new Promise(resolve => setTimeout(resolve, 800));
      
      // Simple admin validation - in a real app, this would be a backend call
      if (username === 'admin' && password === 'loremipsum') {
        const adminData = {
          name: 'Admin',
          username: 'admin',
          role: 'admin'
        };
        
        // Save admin data in localStorage
        localStorage.setItem('adminData', JSON.stringify(adminData));
        
        // Call success callback
        if (onLoginSuccess) {
          onLoginSuccess(adminData);
        }
        
        // Close modal
        if (onClose) {
          onClose();
        }
      } else {
        setError('Invalid administrator credentials');
      }
    } catch (error) {
      setError('Login failed. Please try again.');
      console.error('Login error:', error);
    } finally {
      setIsLoading(false);
    }
  };
  
  return (
    <div className="fixed inset-0 flex items-center justify-center z-50 bg-black bg-opacity-75">
      <div className="bg-gray-900 rounded-lg shadow-xl border border-green-500/30 max-w-md w-full mx-4">
        {/* Close button */}
        <button 
          onClick={onClose}
          className="absolute top-3 right-3 text-gray-400 hover:text-white transition-colors"
          aria-label="Close"
        >
          <X size={20} />
        </button>
        
        {/* Header with icon */}
        <div className="px-6 pt-6 pb-4 flex items-center justify-center flex-col">
          <div className="w-12 h-12 bg-green-500/20 rounded-full flex items-center justify-center mb-4">
            <User size={24} className="text-green-400" />
          </div>
          <h2 className="text-green-400 text-2xl font-bold flex items-center">
            <span className="mr-2">Admin Login</span>
          </h2>
        </div>
        
        {/* Form */}
        <form onSubmit={handleSubmit} className="px-6 pb-4 space-y-4">
          {/* Error message */}
          {error && (
            <div className="bg-red-900/50 border border-red-500 text-white p-3 rounded text-sm">
              {error}
            </div>
          )}
          
          {/* Username */}
          <div>
            <label htmlFor="username" className="block text-green-400 text-sm mb-1">Username</label>
            <div className="relative">
              <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                <User size={16} className="text-gray-400" />
              </div>
              <input
                id="username"
                type="text"
                value={username}
                onChange={(e) => setUsername(e.target.value)}
                className="block w-full pl-10 pr-3 py-2 rounded-md bg-gray-800 border border-gray-700 text-white focus:border-green-400 focus:outline-none"
                placeholder="Enter admin username"
              />
            </div>
          </div>
          
          {/* Password */}
          <div>
            <label htmlFor="password" className="block text-green-400 text-sm mb-1">Password</label>
            <div className="relative">
              <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                <Lock size={16} className="text-gray-400" />
              </div>
              <input
                id="password"
                type="password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className="block w-full pl-10 pr-3 py-2 rounded-md bg-gray-800 border border-gray-700 text-white focus:border-green-400 focus:outline-none"
                placeholder="Enter password"
              />
            </div>
          </div>
          
          {/* Default password notice */}
          <p className="text-gray-400 text-xs">
            Default first-time password: "loremipsum"
          </p>
          
          {/* Submit button */}
          <button
            type="submit"
            disabled={isLoading}
            className="w-full bg-green-600 hover:bg-green-500 text-black font-medium py-2 px-4 rounded flex items-center justify-center transition-colors"
          >
            {isLoading ? (
              <span>Logging in...</span>
            ) : (
              <>
                <LogIn size={18} className="mr-2" />
                <span>Login</span>
              </>
            )}
          </button>
        </form>
        
        {/* Admin notice */}
        <div className="px-6 py-4 bg-gray-800/50 rounded-b-lg border-t border-gray-700 text-sm text-gray-400">
          This login is only for site administrators. Guests do not need to log in to browse content.
        </div>
      </div>
    </div>
  );
};

export default AdminLogin;