import React from 'react';
import { createRoot } from 'react-dom/client';
import Router from './Router';
import { AuthProvider } from './components/AuthContext';
import './styles/styles.css';
import './styles/masteryhub.css';
import './styles/transitions.css';
import './styles/wikidedia.css';

// Importa gli stili per gli elementi di autenticazione
import './styles/auth.css';

const container = document.getElementById('root');
const root = createRoot(container);

// Wrappa l'applicazione con AuthProvider per fornire lo stato di autenticazione a tutti i componenti
root.render(
  <React.StrictMode>
    <AuthProvider>
      <Router />
    </AuthProvider>
  </React.StrictMode>
);