import React, { createContext, useState, useEffect, useContext } from 'react';
import { API_URL } from '../config';

// Creazione del context
const AuthContext = createContext();

// Hook personalizzato per accedere al context
export const useAuth = () => useContext(AuthContext);

// Provider component
export const AuthProvider = ({ children }) => {
  // Stati principali
  const [user, setUser] = useState(null);
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [isAdmin, setIsAdmin] = useState(false);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // Controlla lo stato di autenticazione all'avvio
  useEffect(() => {
    const checkAuthStatus = async () => {
      try {
        // Verifica se esiste un token nel localStorage
        const token = localStorage.getItem('authToken');
        
        if (!token) {
          setLoading(false);
          return;
        }
        
        // Verifica la validità del token con il server
        const response = await fetch(`${API_URL}/auth/verify`, {
          method: 'GET',
          headers: {
            'Authorization': `Bearer ${token}`
          }
        });
        
        if (response.ok) {
          const userData = await response.json();
          setUser(userData);
          setIsAuthenticated(true);
          setIsAdmin(userData.role === 'admin');
        } else {
          // Token invalido o scaduto
          localStorage.removeItem('authToken');
        }
      } catch (err) {
        console.error('Error checking authentication status:', err);
        setError('Authentication check failed');
      } finally {
        setLoading(false);
      }
    };
    
    checkAuthStatus();
  }, []);

  // Funzione di login
  const login = async (email, password) => {
    setLoading(true);
    setError(null);
    
    try {
      const response = await fetch(`${API_URL}/auth/login`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({ email, password })
      });
      
      if (!response.ok) {
        throw new Error('Login failed');
      }
      
      const data = await response.json();
      
      // Salva il token nel localStorage
      localStorage.setItem('authToken', data.token);
      
      // Aggiorna lo stato
      setUser(data.user);
      setIsAuthenticated(true);
      setIsAdmin(data.user.role === 'admin');
      
      return data.user;
    } catch (err) {
      setError(err.message || 'Login failed');
      throw err;
    } finally {
      setLoading(false);
    }
  };

  // Funzione di logout
  const logout = () => {
    localStorage.removeItem('authToken');
    setUser(null);
    setIsAuthenticated(false);
    setIsAdmin(false);
  };

  // Per ambienti di sviluppo/test: permette di simulare il login come admin o guest
  // Utile prima di implementare completamente il backend
  const simulateLogin = (role = 'guest') => {
    const mockUser = {
      id: '123',
      name: role === 'admin' ? 'Admin User' : 'Guest User',
      email: role === 'admin' ? 'admin@example.com' : 'guest@example.com',
      role: role
    };
    
    setUser(mockUser);
    setIsAuthenticated(true);
    setIsAdmin(role === 'admin');
    
    // Salva nel localStorage per persistenza
    localStorage.setItem('mockUserRole', role);
  };

  // Controlla se l'utente simulato esiste nel localStorage al caricamento
  useEffect(() => {
    if (process.env.NODE_ENV === 'development') {
      const mockRole = localStorage.getItem('mockUserRole');
      if (mockRole && !isAuthenticated && !loading) {
        simulateLogin(mockRole);
      }
    }
  }, [loading, isAuthenticated]);

  // Espone l'API del context
  const value = {
    user,
    isAuthenticated,
    isAdmin,
    loading,
    error,
    login,
    logout,
    simulateLogin // Solo per sviluppo/test
  };
  
  return (
    <AuthContext.Provider value={value}>
      {children}
    </AuthContext.Provider>
  );
};

export default AuthProvider;